(()=>{
const asset=n=>'assets/refine/'+n;
const im=(n,alt='',cls='')=>'<img class="'+cls+'" src="'+asset(n)+'" alt="'+alt+'">';
const fm={expanded:false,zoom:1,x:0,y:0,selected:4,query:""};
const cats=[['Batch processing',271,170],['Business logic changes',935,120],['Performance optimization',1376,95],['Data & interfaces',1388,390],['Modernization & refactoring',1354,613],['Regression testing',1071,676],['Team handover',128,665],['Testing & validation',316,404]];
const cases=[['Fix a duplicate refund after restart',609,282,'refund'],['Resolve an S0C7 in payment processing',484,323,'s0c7'],['Investigate a missing settlement record',723,336,'missing'],['Fix an incorrect month-end fee',707,548,'fee'],['Resolve a customer record update failure',573,594,'update']];
const baseKnowledge=knowledge,baseBind=bindKnowledge;
const shell=()=>'<header class="mac-titlebar"><div class="mac-traffic"><button class="mac-close" data-action="kb-desktop" aria-label="Close Knowledge window"><span>×</span></button><button class="mac-minimize" data-action="kb-desktop" aria-label="Minimize Knowledge window"><span>−</span></button><button class="mac-maximize" data-action="kb-maximize" aria-label="Toggle full screen"><span>↗</span></button></div><strong>Knowledge</strong></header>';
function rail(){return '<nav class="rf-rail"><button data-rf="home" class="active" aria-label="Knowledge">'+im('32f62.svg')+'<small>Knowledge</small></button><button data-action="kb-view:pool" aria-label="Pool">'+im('fe3e0.svg')+'<small>Pool</small></button><div class="rf-bottom"><button data-action="pool-downloads" aria-label="Downloads">'+im('3df5f.svg')+'</button><button class="rf-user" data-nb="review" aria-label="Today’s review">u</button></div></nav>'}
function actions(){return '<div class="rf-actions" style="left:588px;top:'+(fm.expanded?693:534)+'px"><small>NEW CAPTURE · IN POOL</small><div><button data-rf="explore">Explore</button><button data-rf="edit" aria-label="Edit knowledge">'+im('5824f.svg')+'</button><button data-action="kb-view:pool" class="rf-manage">Manage pool '+im('f55cf.svg')+'</button></div></div>'}
function matchesTicket(id,label){const t=window.demoTickets[id];return !fm.query||(t.id+' '+t.project+' '+label).toLowerCase().includes(fm.query.toLowerCase())}
function canvas(){return '<div class="rf-stage"><div class="rf-art">'+im(fm.expanded?'11394.svg':'47dd9.svg','','rf-lines')+
(fm.expanded?im('711ab.png','','rf-orbit'):'')+
cats.map(([label,x,y],i)=>'<button class="rf-category" style="left:'+(fm.expanded&&i===7?65:x)+'px;top:'+y+'px" data-rf="category" data-index="'+i+'">'+esc(label)+'</button>').join('')+
'<button class="rf-category rf-main" style="left:588px;top:424px" data-rf="toggle" aria-expanded="'+fm.expanded+'">Debugging<br>& incidents<span>'+(fm.expanded?'−':'+')+'</span></button>'+
(fm.expanded?cases.map(([label,x,y,id],i)=>'<button class="rf-case '+(fm.selected===i?'selected':'')+(fm.query?(matchesTicket(id,label)?' ticket-match':' ticket-muted'):'')+'" style="left:'+x+'px;top:'+y+'px" data-nb="refine-case:'+id+'" aria-label="'+esc(label)+'">'+im(i===0?'11812.svg':'0cb28.svg')+'<span>'+esc(label)+'</span><span class="rf-ticket-tip" role="tooltip"><strong>'+esc(window.demoTickets[id].id)+' · '+esc(window.demoTickets[id].project)+'</strong><small>Investigated across '+window.demoTickets[id].sessions+' work sessions</small></span></button>').join(''):'')+actions()+'</div></div>'}
knowledge=function(){if(kb.view!=='map'){const html=baseKnowledge();return kb.view==='notebook'?html.replace(/<nav class="nb-rail">[\s\S]*?<\/nav>/,rail()).replaceAll('assets/companion-blue-spirit.svg',asset('a6f09.png')):html;}document.title='Hypercubic — Knowledge';return '<div class="wallpaper"></div><main class="knowledge-app rf-app '+(kb.maximized?'maximized':'')+'">'+shell()+rail()+'<section class="rf-map" aria-label="Knowledge work types">'+canvas()+'<div class="rf-zoom"><button data-rf="out" aria-label="Zoom out">−</button><span>'+Math.round(fm.zoom*100)+'%</span><button data-rf="in" aria-label="Zoom in">+</button><button data-rf="fit">Fit</button></div><form class="rf-composer" id="rf-chat">'+im('a6f09.png','Companion')+'<input aria-label="Ask about this knowledge" placeholder="Search a ticket or ask about this knowledge…" value="'+esc(fm.query)+'" required><button aria-label="Send question">↑</button></form>'+(fm.expanded?'<div class="rf-prompts"><button data-rf="why">Why this change?</button><button data-rf="check">How was it checked?</button><button data-rf="source">Show the source</button></div>':'')+'</section></main>'};
function layout(){const stage=document.querySelector('.rf-stage');if(!stage)return;const scale=Math.min(stage.clientWidth/1659,stage.clientHeight/855);stage.style.setProperty('--rf-scale',scale*fm.zoom);stage.style.setProperty('--rf-x',fm.x+'px');stage.style.setProperty('--rf-y',fm.y+'px')}
bindKnowledge=function(){if(kb.view!=='map')return baseBind();layout();const stage=document.querySelector('.rf-stage');stage.onclick=e=>{if(!e.target.closest('button')){fm.expanded=false;render()}};stage.onwheel=e=>{e.preventDefault();if(e.ctrlKey||e.metaKey)fm.zoom=Math.max(.6,Math.min(2.5,fm.zoom*Math.exp(-e.deltaY*.008)));else{fm.x-=e.deltaX;fm.y-=e.deltaY}layout();document.querySelector('.rf-zoom span').textContent=Math.round(fm.zoom*100)+'%'};const form=document.querySelector('#rf-chat');form.querySelector('input').oninput=e=>{if(!e.target.value&&fm.query){fm.query='';document.querySelectorAll('.ticket-match,.ticket-muted').forEach(el=>el.classList.remove('ticket-match','ticket-muted'))}};form.onsubmit=e=>{e.preventDefault();fm.query=form.querySelector('input').value.trim();fm.expanded=true;const count=cases.filter(c=>matchesTicket(c[3],c[0])).length;render();toast(count?count+' matching case'+(count===1?'':'s')+'. Select a highlighted node.':'No matching ticket or case. Clear the search to see all cases.')}};
window.addEventListener('resize',layout);
document.addEventListener('click',e=>{const b=e.target.closest('[data-rf]');if(!b)return;const a=b.dataset.rf;if(a==='toggle'||a==='explore')fm.expanded=!fm.expanded;else if(a==='home'){kb.view='map';fm.expanded=false;fm.query='';history.replaceState(null,'','#knowledge')}else if(a==='in')fm.zoom=Math.min(2.5,fm.zoom*1.2);else if(a==='out')fm.zoom=Math.max(.6,fm.zoom/1.2);else if(a==='fit'){fm.zoom=1;fm.x=0;fm.y=0}else if(a==='category'){toast(cats[Number(b.dataset.index)][0]+' — no cases added in this prototype yet.');return}else{fm.expanded=true;toast(a==='edit'?'Open a case to edit its knowledge.':'Choose a case to explore its reasoning and sources.')}render()});
if(state.screen==='knowledge')render();
})();
